import{_ as r,W as p,s as o,u as l,ah as d,I as i,w as s,Z as a,A as t}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const U=JSON.parse('{"title":"如何在 XenServer 7 GUI 虚拟机（VM）上提高屏幕分辨率 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 XenServer 7 GUI 虚拟机（VM）上提高屏幕分辨率 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 XenServer 7 GUI 虚拟机（VM）上提高屏幕分辨率 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 XenServer 7 GUI 虚拟机（VM）上提高屏幕分辨率 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20161111 How to increase screen resolution on XenServer 7 GUI Virtual Machine","title":"如何在 XenServer 7 GUI 虚拟机（VM）上提高屏幕分辨率","tag":"201702"},"relativePath":"201702/20161111 How to increase screen resolution on XenServer 7 GUI Virtual Machine.md","filePath":"[post].md"}'),u={name:"201702/20161111 How to increase screen resolution on XenServer 7 GUI Virtual Machine.md"};function g(c,e,v,m,h,b){const n=p("Link");return l(),o("div",null,[e[13]||(e[13]=d(`<h1 id="如何在-xenserver-7-gui-虚拟机-vm-上提高屏幕分辨率" tabindex="-1">如何在 XenServer 7 GUI 虚拟机（VM）上提高屏幕分辨率 <a class="header-anchor" href="#如何在-xenserver-7-gui-虚拟机-vm-上提高屏幕分辨率" aria-label="Permalink to 如何在 XenServer 7 GUI 虚拟机（VM）上提高屏幕分辨率">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to 介绍">​</a></h3><p><strong>目的</strong></p><p>如果你想要将 XenServer 虚拟机作为远程桌面，默认的分辨率可能不能满足你的要求。</p><p><img src="https://linuxconfig.org/images/xenserver-7-default-screen-resolution.png" alt="Default xenserver screen VM resolution"></p><p>本篇的目标是提高 XenServer 7 GUI 虚拟机（VM）的屏幕分辨率</p><p><strong>要求</strong></p><p>访问 XenServer 7 系统的权限</p><p><strong>难易性</strong></p><p>简单</p><p><strong>惯例</strong></p><ul><li><code>#</code> - 给定命令需要作为 root 用户权限运行或者使用 <code>sudo</code> 命令</li><li><code>$</code> - 给定命令作为常规权限用户运行</li></ul><h3 id="指导" tabindex="-1">指导 <a class="header-anchor" href="#指导" aria-label="Permalink to 指导">​</a></h3><p><strong>获得 VM UUID</strong></p><p>首先，我们需要获得想要提升分辨率的虚拟机的 UUID。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># xe vm-list </span></span>
<span class="line"><span>uuid ( RO)           : 09a3d0d3-f16c-b215-9460-50dde9123891</span></span>
<span class="line"><span>     name-label ( RW): CentOS 7</span></span>
<span class="line"><span>    power-state ( RO): running</span></span></code></pre></div><p>提示：如果你将此 UUID 保存为 shell 变量会节省一些时间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># UUID=09a3d0d3-f16c-b215-9460-50dde9123891</span></span></code></pre></div><p><strong>关闭 VM</strong></p><p>优雅地关闭 VM 或使用 <code>xe vm-vm-shutdown</code> 命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># xe vm-shutdown uuid=$UUID</span></span></code></pre></div><p><strong>更新 VGA 的 VIDEORAM 设置</strong></p><p>检查你目前的 VGA 的 VIDEORAM 参数设置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># xe vm-param-get uuid=$UUID param-name=&quot;platform&quot; param-key=vga</span></span>
<span class="line"><span>std</span></span>
<span class="line"><span># xe vm-param-get uuid=$UUID param-name=&quot;platform&quot; param-key=videoram</span></span>
<span class="line"><span>8</span></span></code></pre></div><p>要提升屏幕的分辨率，将 VGA 更新到 <code>std</code> （如果已经设置过，就不需要做什么），并将 <code>videoram</code> 调大几兆，如设置成 16：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># xe vm-param-set uuid=$UUID platform:vga=std</span></span>
<span class="line"><span># xe vm-param-set uuid=$UUID platform:videoram=16</span></span></code></pre></div><p><strong>启动 VM</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># xe vm-start uuid=$UUID</span></span></code></pre></div><p><img src="https://linuxconfig.org/images/xenserver-7-increased-screen-resolution.png" alt="increased xenserver screen VM resolution"></p><hr>`,30)),i("p",null,[e[1]||(e[1]=s("via: ")),a(n,{href:"https://linuxconfig.org/how-to-increase-screen-resolution-on-xenserver-7-gui-virtual-machine-vm"},{default:t(()=>e[0]||(e[0]=[s("https://linuxconfig.org/how-to-increase-screen-resolution-on-xenserver-7-gui-virtual-machine-vm")])),_:1})]),i("p",null,[e[5]||(e[5]=s("作者：")),a(n,{href:"https://linuxconfig.org/how-to-increase-screen-resolution-on-xenserver-7-gui-virtual-machine-vm"},{default:t(()=>e[2]||(e[2]=[s("Lubos Rendek")])),_:1}),e[6]||(e[6]=s(" 译者：")),a(n,{href:"https://github.com/geekpi"},{default:t(()=>e[3]||(e[3]=[s("geekpi")])),_:1}),e[7]||(e[7]=s(" 校对：")),a(n,{href:"https://github.com/wxy"},{default:t(()=>e[4]||(e[4]=[s("wxy")])),_:1})]),i("p",null,[e[10]||(e[10]=s("本文由 ")),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>e[8]||(e[8]=[s("LCTT")])),_:1}),e[11]||(e[11]=s(" 原创编译，")),a(n,{href:"https://linux.cn/"},{default:t(()=>e[9]||(e[9]=[s("Linux中国")])),_:1}),e[12]||(e[12]=s(" 荣誉推出"))])])}const k=r(u,[["render",g]]);export{U as __pageData,k as default};
